@extends('layouts.app') @section('content')<div class="top"><div><h1>Real-Time Inventory Tracking</h1><p class="muted">Lab 6 stock movements connected to Lab 7 replenishment.</p></div><a class="btn secondary" href="{{ route('dashboard') }}">Back to Dashboard</a></div><form class="form" method="post" action="{{ route('inventory.store') }}">@csrf<label>Product</label><select name="product_id" required>@foreach($products as $product)<option value="{{ $product->id }}">{{ $product->sku }} - {{ $product->name }} ({{ $product->quantity_on_hand }} on hand)</option>@endforeach</select><label>Transaction type</label><select name="transaction_type"><option value="stock_in">Stock in</option><option value="stock_out">Stock out</option></select><label>Quantity</label><input type="number" name="quantity" min="1" required><label>Reference document</label><input name="reference_document" placeholder="Invoice or sales reference"><label>Notes</label><textarea name="notes"></textarea><br><br><button class="btn">Save Inventory Movement</button></form><h2>Recent inventory transactions</h2><table><tr><th>Date</th><th>Product</th><th>Type</th><th>Quantity</th><th>Before</th><th>After</th></tr>@foreach($transactions as $tx)<tr><td>{{ optional($tx->created_at)->format('M d, Y H:i') }}</td><td>{{ $tx->product?->name }}</td><td>{{ $tx->transaction_type ?: $tx->type }}</td><td>{{ $tx->quantity }}</td><td>{{ $tx->quantity_before }}</td><td>{{ $tx->quantity_after }}</td></tr>@endforeach</table>{{ $transactions->links() }}@endsection
